from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True, slots=True)
class Constant:
    value: Any


@dataclass(frozen=True, slots=True)
class SymbolRef:
    name: str


@dataclass(frozen=True, slots=True)
class IndexedRef:
    base: str
    index: int | str


@dataclass(frozen=True, slots=True)
class BinaryTerm:
    op: str
    left: Term
    right: Term


@dataclass(frozen=True, slots=True)
class FuncCall:
    name: str
    args: tuple[Term, ...]


Term = Constant | SymbolRef | IndexedRef | BinaryTerm | FuncCall


@dataclass(frozen=True, slots=True)
class Compare:
    op: str
    left: Term
    right: Term


@dataclass(frozen=True, slots=True)
class BoolConst:
    value: bool


@dataclass(frozen=True, slots=True)
class BoolNot:
    value: Formula


@dataclass(frozen=True, slots=True)
class BoolAnd:
    values: tuple[Formula, ...]


@dataclass(frozen=True, slots=True)
class BoolOr:
    values: tuple[Formula, ...]


@dataclass(frozen=True, slots=True)
class Implies:
    left: Formula
    right: Formula


@dataclass(frozen=True, slots=True)
class ForAll:
    variable: str
    domain: tuple[Any, ...]
    body: Formula


@dataclass(frozen=True, slots=True)
class Exists:
    variable: str
    domain: tuple[Any, ...]
    body: Formula


Formula = Compare | BoolConst | BoolNot | BoolAnd | BoolOr | Implies | ForAll | Exists


def constant(value: Any) -> Constant:
    return Constant(value=value)


def render_keyword(value: str) -> str:
    return value.upper()


